.bar{position:sticky;top:env(safe-area-inset-top,0px);z-index:5;display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:8px 12px;background:var(--bar-bg);color:var(--bar-ink);font-size:13px;border-bottom:1px solid #8884}

