/* ---------- INVOICE: fixed A4 ---------- */

.page{width:210mm;min-height:296mm;padding:8mm;box-sizing:border-box;background:#fff;color:#000;font-size:9.5pt;line-height:1.35;box-shadow:0 2px 14px #0004}

