.sig{flex:1;min-height:36mm;position:relative;display:flex;flex-direction:column;justify-content:space-between;text-align:center;padding:2mm 3mm 1.5mm;font-size:9.5pt}

.sig b{position:relative;z-index:1;font-size:10pt}

.wm{position:absolute;left:50%;top:50%;width:30mm;height:26mm;transform:translate(-50%,-50%);object-fit:contain;opacity:.12;z-index:0}

.wm.ph{border:1pt dashed #bbb;opacity:.5}

.sig .sg{position:relative;z-index:1;border-top:.6pt dashed #000;padding-top:1mm;margin:0 6mm}

