/* ---------- print ---------- */

@page{size:A4 portrait;margin:0}

@media print{html,body{background:#fff}.bar{display:none}.stage{padding:0;display:block;overflow:visible}#zoomer{transform:none!important;width:auto!important;height:auto!important}.page{box-shadow:none}.bot{break-inside:avoid}}

</style></head>

<body>

<div class="bar">

