</div>

<div class="stage"><div id="zoomer"><div id="inv"></div></div></div>



<script>

/* =====================================================================

   1. CONFIG + DATA MODEL  (replace with Flutter-provided data)

   ===================================================================== */

const CONFIG = {

  logo: "data:image/png;base64,", // <-- set to company logo URL / data-URI. Same asset feeds header + watermark.

  company: {

    name: "ARUN MENSWARE SERVICE", tagline: "Safety Items & Industrial Suppliers",

    address: "Laxmi Chhaya Society-1, Plot No 177, 25 Mtr, 150 Feet Ring Road, Rajkot, Gujarat - 360005",

    phone: "+91 9824417257", email: "Arunmsws@gmail.com", gstin: "24AKZPP9424E1ZM",

    bank: { name: "HDFC Bank Rajkot", account: "03792000003498", ifsc: "HDFC0000379", email: "Arunmsws@gmail.com" },

    terms: ["Interest @ 21% p.a. will be charged if bill is not paid on due date.","Goods once sold will not be taken back.","All disputes subject to Rajkot Jurisdiction."]

  }

};

const SAMPLE = {

  invoiceNumber:"INV-0037", date:"04/10/2026", challanNumber:"120", transportBy:"DTDC Courier", lrNumber:"-", lrDate:"04 Oct 2026",

  buyer:{ name:"PGP Glass Private Limited", address:"Plot No 412, Gate 3, Lodhika GIDC, Metoda, Rajkot, Gujarat - 360021", gstin:"24AALCP5737F1ZA", sst:"" },

  items:[

    { productName:"High-Vis Vests", description:"(20*09 = 10)", hsn:"6216", quantity:500, unit:"Piece", rate:20.60, poNumber:"PO-2026/881", poQuantity:500 },

    { productName:"Cotton Hand Gloves", description:"", hsn:"6116", quantity:100, unit:"Pair", rate:35.36, poNumber:"PO-2026/882", poQuantity:100 }

  ],

  parcelNo:"10", taxType:"CGST_SGST", otherExpense:0

};

const it = (p,d,h,q,u,r,po,pq)=>({productName:p,description:d,hsn:h,quantity:q,unit:u,rate:r,poNumber:po,poQuantity:pq??q});

const CASES = {

 "1 · One item, no description":{items:[it("Cotton Hand Gloves","","6116",500,"Qty.",35,"PO-2026/881")]},

 "2 · One item + description":{items:[it("High-Vis Vests","(20*09 = 10)","6216",500,"Piece",20.6,"PO-2026/881")]},

 "3 · Two items, different POs":{},

 "4 · Five items with descriptions":{items:[

   it("High-Vis Vests","(20*09 = 10)","6216",500,"Piece",20.6,"PO-2026/881"),it("Cotton Hand Gloves","Terry towel, 10 inch","6116",1200,"Pair",35.36,"PO-2026/882"),

   it("Safety Helmet","Yellow, ISI marked","6506",50,"Nos.",185,"PO-2026/884"),it("Safety Shoes","Steel toe, size 8-10","6402",40,"Pair",640,"PO-2026/885"),

   it("Face Mask N95","","6307",300,"Piece",12.5,"PO-2026/886")]},

 "5 · Long buyer company name":{buyer:{name:"Shree Ganeshkrupa Industrial Safety & Allied Engineering Works Private Limited (Unit II)",address:"Plot No 412, Gate 3, Lodhika GIDC, Metoda, Rajkot, Gujarat - 360021",gstin:"24AALCP5737F1ZA"}},

 "6 · Long buyer address":{buyer:{name:"PGP Glass Private Limited",address:"Survey No. 118/2 Paiki, Block No. 77, Behind Shree Ram Weigh Bridge, Near Lodhika Chowkdi, Lodhika GIDC Industrial Estate, Village Metoda, Taluka Lodhika, Rajkot, Gujarat - 360021",gstin:"24AALCP5737F1ZA",sst:"S.S.T. 24-0987-6543"}},

 "7 · Large quantity":{items:[it("Cotton Hand Gloves","","6116",1250000,"Pair",3.5,"PO-2026/890",1250000)]},

 "8 · Large amount":{items:[it("Industrial Safety Harness","Full body, double lanyard","6307",8500,"Nos.",12450.75,"PO-2026/891")]},

 "9 · Duplicate copy":{_copy:"DUPLICATE"},

 "10 · CGST + SGST":{taxType:"CGST_SGST"},

 "11 · IGST":{taxType:"IGST",buyer:{name:"Mehta Safety Traders",address:"B-14, Okhla Industrial Area Phase II, New Delhi - 110020",gstin:"07AAAPM1234C1Z5"}},

 "12 · No LR number":{lrNumber:"",otherExpense:150},

 "13 · Long product description":{items:[it("Cotton Hand Gloves","Knitted cotton terry towel fabric, double stitched hem, elastic wrist band, reinforced thumb, available in white/grey, packed 12 pairs per dozen bag, 10 dozen per carton, with brand label printed on the cuff as per buyer specification sheet rev. 4","6116",500,"Pair",35,"PO-2026/881")]}

};



/* =====================================================================

   2. HELPERS

   ===================================================================== */

const esc = s => String(s ?? "").replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));

const money = n => Number(n).toLocaleString("en-IN",{minimumFractionDigits:2,maximumFractionDigits:2});

const qtyFmt = n => Number(n).toLocaleString("en-IN");

const r2 = n => Math.round((n + Number.EPSILON) * 100) / 100;

const ONES=["","One","Two","Three","Four","Five","Six","Seven","Eight","Nine","Ten","Eleven","Twelve","Thirteen","Fourteen","Fifteen","Sixteen","Seventeen","Eighteen","Nineteen"];

const TENS=["","","Twenty","Thirty","Forty","Fifty","Sixty","Seventy","Eighty","Ninety"];

function below1000(n){let s="";if(n>=100){s+=ONES[Math.floor(n/100)]+" Hundred ";n%=100}if(n>=20){s+=TENS[Math.floor(n/10)]+" "+ONES[n%10]+" "}else if(n>0)s+=ONES[n]+" ";return s}

function words(n){ // Indian numbering

  if(n===0)return"Zero";let s="";

  const cr=Math.floor(n/1e7);n%=1e7;const lk=Math.floor(n/1e5);n%=1e5;const th=Math.floor(n/1e3);n%=1e3;

  if(cr)s+=below1000(cr)+"Crore ";if(lk)s+=below1000(lk)+"Lakh ";if(th)s+=below1000(th)+"Thousand ";s+=below1000(n);return s.trim()}

function amountInWords(total){const rs=Math.floor(total),ps=Math.round((total-rs)*100);

  return "Rupees "+words(rs)+(ps?" and "+words(ps)+" Paise":"")+" Only"}



/* totals are always derived from items – never hardcoded */

function computeTotals(d){

  const items=d.items.map(i=>({...i,amount:r2(i.quantity*i.rate)}));

  const sub=r2(items.reduce((a,i)=>a+i.amount,0));

  const other=Number(d.otherExpense||0);

  let cgst=0,sgst=0,igst=0;

  if(d.taxType==="IGST"){igst=r2(sub*0.05)}else{const t=sub*0.05;cgst=r2(t/2);sgst=r2(t-r2(t/2))}

  return {items,sub,other,cgst,sgst,igst,grand:r2(sub+other+cgst+sgst+igst)};

}



/* =====================================================================

   3. INVOICE RENDERER  (pure: data + copyType + logo -> HTML)

   ===================================================================== */

function logoTag(logo,cls,ph){return logo?`<img class="${cls}" src="${esc(logo)}" alt="">`:`<div class="${ph}">LOGO</div>`}

function renderInvoice(d, invoiceCopyType="ORIGINAL", logo=CONFIG.logo, co=CONFIG.company){

  const t=computeTotals(d);

  const copyLabel=invoiceCopyType==="DUPLICATE"?"TAX INVOICE (DUPLICATE)":"TAX INVOICE (ORIGINAL FOR RECIPIENT)";

  const rows=t.items.map((i,n)=>{const sp=n?" sep":"";return `

    <div class="n${sp}">${n+1}</div>

    <div class="${sp}"><div class="pn">${esc(i.productName)}</div>${i.description&&i.description.trim()?`<div class="ds">${esc(i.description)}</div>`:""}${i.poNumber?`<div class="po">PO: ${esc(i.poNumber)} (${qtyFmt(i.poQuantity)} ${esc(i.unit)})</div>`:""}</div>

    <div class="n${sp}">${esc(i.hsn)}</div><div class="r${sp}">${qtyFmt(i.quantity)} ${esc(i.unit)}</div>

    <div class="r${sp}">${money(i.rate)}</div><div class="r${sp}"><b>${money(i.amount)}</b></div>`}).join("");

  const taxRows=d.taxType==="IGST"?`<div><span>ADD. IGST @ 5%</span><span>₹ ${money(t.igst)}</span></div>`

    :`<div><span>ADD. CGST @ 2.5%</span><span>₹ ${money(t.cgst)}</span></div><div><span>ADD. SGST @ 2.5%</span><span>₹ ${money(t.sgst)}</span></div>`;

  const kv=(k,v,b)=>`<span>${k}</span><span>:</span><b${b?' class="s"':""}>${esc(v||"-")}</b>`;

  return `<div class="page"><div class="sheet">

  <div class="hdr">${logoTag(logo,"logo","logo-ph")}

    <div class="co"><h1>${esc(co.name)}</h1><div class="tag">${esc(co.tagline)}</div>

      <div class="ad">${esc(co.address)}<br>Phone: ${esc(co.phone)} &nbsp;|&nbsp; Email: ${esc(co.email)}</div></div>

    <div class="gst">GSTIN<b>${esc(co.gstin)}</b></div></div>

  <div class="title">${copyLabel}</div>

  <div class="body">

  <div class="info">

    <div class="box"><div class="bh">INVOICE DETAILS</div><div class="in"><div class="kv">${kv("Invoice No.",d.invoiceNumber,1)}${kv("Date",d.date)}${kv("Challan No.",d.challanNumber)}${kv("Transport By",d.transportBy)}${kv("LR No.",d.lrNumber)}${kv("LR Date",d.lrDate)}</div></div></div>

    <div class="box"><div class="bh">BUYER DETAILS</div><div class="in"><div class="kv">${kv("M/s",d.buyer.name,1)}${kv("Address",d.buyer.address)}${kv("GSTIN",d.buyer.gstin,1)}${d.buyer.sst?kv("S.S.T",d.buyer.sst):""}</div></div></div></div>

  <div class="tw">

    <div class="h">SR.<br>NO.</div><div class="h">DESCRIPTION OF GOODS</div><div class="h">HSN<br>CODE</div><div class="h">QTY.</div><div class="h">RATE<br>(₹)</div><div class="h">AMOUNT<br>(₹)</div>

    ${rows}

    <div class="fl"></div><div class="fl"></div><div class="fl"></div><div class="fl"></div><div class="fl"></div><div class="fl"></div>

    <div class="ft" style="grid-column:1/3;justify-content:space-between;padding:0"><span style="padding:1.8mm 3mm;border-right:.6pt solid #000;height:100%;display:flex;align-items:center">PARCEL NO. :</span><span style="flex:1;text-align:center;font-weight:500">${esc(d.parcelNo||"—")}</span></div>

    <div class="ft" style="grid-column:3/6">SUB TOTAL</div><div class="ft v">₹ ${money(t.sub)}</div>

  </div>

  <div class="bot">

    <div class="col">

      <div class="box"><div class="bh">BANK DETAILS</div><div class="bank"><div class="kv">${kv("Bank Name",co.bank.name)}${kv("Bank Account",co.bank.account)}${kv("IFSC",co.bank.ifsc)}${kv("Email",co.bank.email)}</div></div></div>

      <div class="box terms"><div class="bh">TERMS &amp; CONDITIONS</div><ol>${co.terms.map(x=>`<li>${esc(x)}</li>`).join("")}</ol></div></div>

    <div class="col">

      <div class="box tot"><div><span>SUB TOTAL</span><span>₹ ${money(t.sub)}</span></div>

        ${t.other?`<div><span>OTHER EXP.</span><span>₹ ${money(t.other)}</span></div>`:""}${taxRows}

        <div class="g"><span>GRAND TOTAL</span><span>₹ ${money(t.grand)}</span></div></div>

      <div class="box words"><b>In Words :</b><span>${amountInWords(t.grand)}</span></div>

      <div class="box sig"><b>${esc(co.name)}</b>${logo?`<img class="wm" src="${esc(logo)}" alt="">`:`<div class="wm ph"></div>`}<div class="sg">Authorised Signatory</div></div></div>

  </div></div>

  <div class="foot"><span>E. &amp; O.E. &nbsp;·&nbsp; This is a Computer Generated Invoice</span><span>For, ${esc(co.name)}</span></div>

  </div></div>`;

}



/* =====================================================================

   4. PREVIEW WIRING (not part of the invoice template)

   ===================================================================== */

const $=id=>document.getElementById(id);

Object.keys(CASES).forEach(k=>$("case").add(new Option(k,k)));

$("case").value="3 · Two items, different POs";

function draw(){

  const c=CASES[$("case").value]||{};

  const data={...SAMPLE,...c}; if(c._copy&&$("copy").value!=="DUPLICATE")$("copy").value=c._copy;

  $("inv").innerHTML=renderInvoice(data,$("copy").value,CONFIG.logo);

  fit();

}

function fit(){const z=$("zoomer"),w=210*3.7795,s=Math.min(1,(window.innerWidth-16)/w);

  z.style.transform=`scale(${s})`;z.style.width=w+"px";z.style.height=(z.firstElementChild.offsetHeight*s)+"px";z.style.marginBottom="0"}

$("case").onchange=()=>{const c=CASES[$("case").value];if(!c._copy)$("copy").value="ORIGINAL";draw()};

$("copy").onchange=draw;

$("logoFile").onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{CONFIG.logo=r.result;draw()};r.readAsDataURL(f)};

addEventListener("resize",fit);

draw();

</script></body></html>''';